mapper.select:
select

from survey_pay_info
where short_url = #{shortUrl,jdbcType=VARCHAR} limit 1;

select ifnull(sum(s.real_pay_money),0) money from survey_pay_info s where s.delete_flag = 0 and s.organ_id = #{staffOrgId}

  and date_format(s.create_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')


  and date_format(s.create_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
